Definition smear (s : Z) : Z :=
  let m1 := Z.lor s (Z.shiftr s 1) in
  let m2 := Z.lor m1 (Z.shiftr m1 2) in
  Z.lor m2 (Z.shiftr m2 4).

Lemma fold_off_eq off slack :
  fold_off off slack =
  (if slack <? off then
     let x := Z.land off (smear slack) in if slack <? x then x - (slack + 1) else x
   else off).
Proof.
