Lemma malloc_core_fast st n g k :
  let sc := size_to_class n in
  let mr := get_meta_rec st g in
  size_overflows n = false -> n < MMAP_THRESHOLD ->
  active st sc = Some g -> 0 < m_avail mr -> 0 <= k -> lowbit (m_avail mr) = 2 ^ k ->
